const bg=ctx.createRadialGradient(500,350,55,500,350,560);bg.addColorStop(0,'#111d31');bg.addColorStop(.72,'#0b1423');bg.addColorStop(1,'#080e19');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
ctx.strokeStyle='rgba(121,160,210,.08)';ctx.lineWidth=1;for(let x=70;x<W;x+=40){ctx.beginPath();ctx.moveTo(x,arena.t);ctx.lineTo(x,arena.b);ctx.stroke()}for(let y=70;y<H;y+=40){ctx.beginPath();ctx.moveTo(arena.l,y);ctx.lineTo(arena.r,y);ctx.stroke()}
