ctx.strokeStyle='rgba(98,240,220,.25)';ctx.lineWidth=2;for(const [x,y,sx,sy] of [[arena.l,arena.t,1,1],[arena.r,arena.t,-1,1],[arena.l,arena.b,1,-1],[arena.r,arena.b,-1,-1]]){ctx.beginPath();ctx.moveTo(x+sx*12,y);ctx.lineTo(x+sx*34,y);ctx.moveTo(x,y+sy*12);ctx.lineTo(x,y+sy*34);ctx.stroke()}
// Tetris board.
const bx=board.x-10,by=board.y-10,bw=board.cols*board.size+20,bh=board.rows*board.size+20;
roundRect(bx,by,bw,bh,14,'rgba(13,21,35,.76)','rgba(140,167,213,.24)');
